  'The next version of you is already being built by who you are today.',
  'You matter here. Fully. Always.',
  'I\'m rooting for you in the biggest way.',
  'You\'re going to be more than okay. I genuinely believe that.',
  'Whatever\'s hard right now — hold it gently. It\'ll ease.',
  'Rest in the knowing that you\'re enough.',
  'Every person who has ever grown had to feel lost first.',
  'The bravest thing anyone has ever done is feel something fully and not run from it.',
  'You can\'t hate yourself into becoming someone you love.',
  'What you feel right now has been felt by everyone who ever mattered. You\'re not alone in the category.',
  'Softness is not the opposite of strength. It\'s often the source of it.',
  'The oldest truth in the world: you cannot pour from empty. Fill yourself first.',
  'Every generation has had to figure out how to carry hard things. You\'re in good company.',
  'There is no time limit on healing. There never has been.',
  'Being gentle with yourself is not new. It\'s the oldest medicine.',
  'Everyone who has ever done something meaningful has had days that felt like nothing was moving.',
  'You know what\'s actually holding you back better than anyone. Don\'t pretend you don\'t.',
  'The version of you that waits for things to feel perfect before starting never starts. That\'s not the version we\'re going for.',
  'Self-awareness is your most valuable asset. Use it to move, not just to understand.',
  'You\'ve spent enough time understanding what\'s wrong. What\'s one thing you could do about it today?',
  'Empathy for yourself is not the same as excusing yourself. You can hold both.',
  'The gap between knowing and doing is the whole game. Which side are you on right now?',
  'You are more in control of how today feels than you\'re giving yourself credit for.',
  'Caring about yourself is not selfish. It\'s what makes you capable of caring about anyone else.',
  'You already know the feeling you\'re chasing. You\'ve felt it before. What got you there?',
  'The version of you that advocates for what you need is the version worth developing.',
  'Is that story you\'re telling yourself accurate, or is it just comfortable?',
  'Are you being gentle with yourself, or are you using softness to avoid something?',
