  'What would you tell someone you loved if they said what you just said to yourself?',
  'Is this actually as permanent as it feels, or is your nervous system just doing its job?',
  'What if the hard thing you\'re avoiding is also the thing that frees you?',
  'Is the version of yourself you\'re being hard on actually failing, or just growing?',
  'What\'s actually happening right now? Name it. Then decide what that means.',
  'Take a breath and just observe — what is the situation, stripped of the story you\'ve added to it?',
  'You\'ve looked at what\'s happening. Now orient: what does this actually mean for you?',
  'Understand the situation, then decide — not react. There\'s a difference.',
  'What\'s one small thing you could do right now that would change how this feels?',
  'Observe what\'s real. Orient to what you actually need. Then make one move.',
  'You\'ve identified the feeling. Now: what does it want from you?',
  'Before you decide anything, get accurate. What\'s true right now versus what you\'re afraid is true?',
  'Once you know what\'s real, the next step usually reveals itself. What\'s real?',
  'Feel it. Name it. Understand what it\'s asking for. Then act on that — even if the action is rest.',
  'You are not your worst day. You are also not just your best. You\'re the whole thing.',
  'The people who love you best will still love you when you\'re not performing okay.',
  'What you\'re carrying quietly deserves to be said out loud at least once.',
  'There\'s a version of you that gets through this that\'s still fully you.',
  'Healing isn\'t returning to who you were. It\'s becoming who you\'re supposed to be.',
  'The fact that you feel things deeply is not a liability.',
  'You\'re allowed to be a work in progress and still be worth knowing.',
  'Your pain is not a character flaw. It\'s information about what matters to you.',
  'Not every hard moment needs to be turned into a lesson. Sometimes it just needs to be felt.',
  'The relationship you\'re building with yourself is the longest relationship of your life. Invest in it.',
  'You don\'t have to be strong about everything all the time.',
  'Being honest about needing help is one of the most sophisticated things a person can do.',
  'You\'re not behind the version of yourself you thought you\'d be by now. You\'re just a different version.',
  'The most powerful thing you can do today might be the most ordinary thing.',
  'Give yourself credit for the things you\'ve held together that nobody else can see.',
  'You deserve the same gentleness you\'d offer without hesitation to someone you love.',
  'The things that break your heart are the things that tell you what you\'re made for.',
  'You\'re allowed to want things to be different while still accepting where you are.',
  'What you\'re feeling is not an overreaction. It\'s a signal worth decoding.',
  'The kindest thing you can do is be honest with yourself about what you actually need.',
  'You don\'t have to minimize what you\'re going through to make it easier for others.',
  'Some things are worth being soft about. You are one of those things.',
  'You get to decide what this moment means. That\'s always been yours.',
  'Reaching out is already the hard part. You did it. The rest follows.',
  'You\'re not broken. You\'re between who you were and who you\'re becoming.',
  'What would change if you trusted yourself a little more than you currently do?',
  'Your effort is real even when the results aren\'t visible yet.',
  'The thing you\'re afraid to need — you\'re allowed to need it.',
  'You bring something to the world that isn\'t replicated elsewhere. Don\'t forget that.',
  'Whatever you\'re in the middle of, you\'re getting through it. That\'s what you always do.',
  'You\'re here. You\'re real. You\'re trying. That\'s the whole thing.',
  'Being tender in a world that rewards hardness takes a kind of courage people underestimate.',
  'You matter beyond the moments when you have everything together.',
  'Whatever version of yourself you bring today — that version is welcome here.',
  'The things you\'re learning about yourself right now will serve you for decades.',
  'You\'re doing the work. It doesn\'t always feel like it. You still are.',
  'The most sustainable form of strength is the kind that starts with honesty.',
  'You\'re allowed to start over as many times as you need. That\'s not weakness.',
  'What feels impossible right now has not always been impossible. Things change.',
