  'The ability to pause before reacting has always separated the wise from the reactive.',
  'Time has always made things smaller. It will do the same here.',
  'Every fog that ever existed eventually lifted. This one is no different.',
  'The capacity to float above a situation and see it clearly has always been available to humans. It\'s available to you.',
  'Breath has always been the fastest route back to the present. Use it.',
  'Every storm in history passed for the people who waited it out.',
  'Altitude has always given clarity. Rise above this for a moment.',
  'Simplicity has always been more durable than complexity. The simple move usually wins.',
  'Zoom out for a second. Is this actually as big as it feels, or does it just need altitude?',
  'The thing that\'s pressing you right now — from five years out, how much does it matter?',
