    "From high enough, every storm looks like weather. That's not dismissal — that's perspective. The storm is real and temporary both.",
    "There has never been a generation that didn't think the world was ending. And yet here we are. That's worth something.",
    "The things that feel most permanent — feelings, circumstances, other people's opinions — are almost always the most temporary.",
    "Every single person who appears to have it together has seasons where they don't. The composed exterior is not the full story.",
    "Gentleness is not softness. It is an active choice to not add to someone's weight when you could.",
    "Most of what we worry about is in the future. Most of what we regret is in the past. The actual moment we're in is usually fine.",
    "The sky hasn't changed. Only the weather moving through it has. You are the sky, not the weather.",
    "Comparison is looking at someone else's exterior and measuring it against your interior. It's inherently unfair.",
