  'Keep going. Morning is real and you will reach it.',
  
    "Every night that has ever felt like it would last forever has eventually given way to morning. Not as a metaphor — as a physical fact.",
    "The thoughts that come in the dark aren't lying to you more than daytime thoughts — they're just louder with fewer distractions.",
    "There's a reason people confess in the dark. The night removes the performance. What's left is closer to truth.",
    "The hardest realizations in human history have happened in sleepless hours. You're not broken — you're awake to something.",
    "Rest is not a luxury. Sleep-deprived people make different decisions than rested ones. Be careful with what you decide right now.",
    "The middle of the night has held everyone who has ever struggled. You are not alone in this room.",
    "Whatever you're feeling amplifies after midnight. That's biology, not prophecy.",
    "The thing that's keeping you awake is trying to tell you something. The question is whether you're ready to hear it.",
    "Some conversations can only happen with yourself. The night is where they tend to take place.",
    "What you're sitting with right now has weight. It deserves to be sat with, not rushed past.",
    "The night has a way of clarifying what the day helped you avoid seeing. That clarity is yours to use.",
    "This quiet hour is not your enemy. But the thoughts you let run unchallenged in it can be.",
    "Here's what's true: everything you're feeling at 2am has a different shape by morning. Sleep is not giving up — it's strategy.",
    "If you're awake and thinking about it this hard, some part of you already knows the answer. What is it?",
    "The version of you that needs to deal with this deserves to be rested first. That's not avoidance — that's preparation.",
    "You're doing the work even now — in the dark, in the quiet. That counts. But be smart about what decisions you make at this hour.",
    "The fact that this is keeping you awake tells you how much it matters. Respect what matters.",
    "Being awake at this hour to work through something real — that's the cost of caring. You pay it because you care.",
    "What would you need to settle in yourself right now to be able to rest?",
    "This isn't the time for big decisions. It might be the time for one honest acknowledgment.",
    "Are you thinking or are you spiraling? There's a difference. Which is this?",
    "What's the version of this that doesn't keep you awake? Have you let yourself imagine it?",
    "The story you're telling yourself at 2am — would it survive morning scrutiny?",
    "What are you actually afraid of? Not the surface version — what's underneath it?",
    "Is the thing keeping you awake something you can actually do something about right now?",
    "Are you rehearsing a conversation you need to have, or avoiding the fact that you need to have it?",
    "What is the most honest thing you could say to yourself about this situation right now?",
    "If you weren't afraid of what it would mean, what would you acknowledge about this?",
    "What would need to be true for you to feel okay enough to sleep? Can you get there?",
    "Is the worry proportional to the actual risk, or has the night amplified it?",
    "In the stillness of this hour, observe: what is actually happening? Not what might happen — what is actually, right now, true?",
    "Orient your understanding: what do you actually know for certain about this situation?",
    "In the dark, decisions feel more permanent than they are. Give yourself permission to not decide tonight.",
    "What small act could you take right now that would help you feel steadier?",
    "Observe your body: what is it telling you? Tension, heaviness, readiness — what's there?",
    "From what you've observed in the quiet of tonight, what has become clearer?",
    "What's the one thing you could put to rest — in your mind — so the rest of you can rest?",
    "Decide: is this something to act on tonight, or something to carry to morning with fresh eyes?",
    "Whatever you're processing in the dark — what would you need to understand about it to let it go for tonight?",
    "The night is good for seeing. Not always for deciding. See clearly. Decide tomorrow.",
    "The dark is honest. What's it honest about for you tonight?",
    "You don't have to sleep to rest. Sometimes just being still is enough.",
    "This hour keeps its own counsel. What you're thinking here doesn't have to go anywhere yet.",
    "You're safe. That's not nothing. Let it mean something.",
    "Whatever is unresolved right now can still be unresolved tomorrow. You don't have to fix it at 3am.",
    "The night will end. Every single one of them has.",
    "There's something brave about sitting with hard things in the dark instead of running from them.",
    "What if the thing keeping you awake is exactly what you need to sit with right now?",
    "You're not alone in what you're carrying. The night holds everyone who's carrying something.",
    "What would feel like enough of a resolution to let you rest?",
    "Your nervous system is working hard right now. Thank it and let it slow down a little.",
    "Let the quiet do something for you tonight, even if it's just holding you.",
    "Hard nights make more sense in the light. The light is coming.",
    "What would peace feel like right now? Even just a small version of it?",
    "You've made it to the quiet side of the hard moments before. You'll make it to the other side of this one.",
    "The things you're holding right now are real. They're also survivable.",
    "Something true about this hour: it belongs to you. No performance required.",
    "You matter to people who are asleep right now. You still matter to them in the dark.",
    "What is one thing you know for certain that's actually okay right now?",
    "The weight you're carrying is real and temporary. Both.",
    "Every person who has ever made it through a hard season spent some nights like this first.",
    "I'm here. Whatever time it is, whatever you're carrying — I'm here.",
    "Softer than you think, stronger than you feel — that's you, right now.",
    "Sometimes the bravest thing is just staying in the room with the hard feeling.",
    "This night is not endless. It just feels that way from inside it.",
    "What do you need right now, even if you're not sure how to get it?",
    "The thing that matters is that you're here. Still here. That counts.",
    "Give yourself credit for how much you're carrying and how far you've come.",
    "Whatever comes after this dark — you'll be part of getting there.",
    "Rest if you can. If you can't, just be gentle with yourself while you wait for morning.",
  
    "The night has always been where the real ones stayed awake. You are in good company across all of history.",
    "What cannot be seen in the light often becomes visible in the dark. That's the trade the night offers.",
    "Every poet, philosopher, and scientist who changed things did so partly in the night. The quiet is the condition, not the obstacle.",
    "Sleep will come when it comes. While you wait, the dark can be useful if you let it.",
    "The night hasn't changed in ten thousand years. What it holds has always been this: the things we haven't said to ourselves.",
    "The quietest hours have always produced the most important realizations. That's not accidental.",
    "You're allowed to use the night for thinking instead of sleeping. But be careful — the thinking runs differently after midnight.",
    "There is a long tradition of people finding truth in the hours when everyone else is asleep. You are in that tradition tonight.",
