    "The act doesn't have to happen tonight. But the decision might need to.",
    "What will you do with what you've understood in the dark, once the light comes?",
    "You're here, in the quiet. That means something.",
    "This hour is honest. Let it be honest with you.",
    "What's here right now that's just yours — not the day, not anyone else's noise?",
    "The dark doesn't need to be the enemy tonight.",
    "Whatever you're sitting with is survivable. It's already been surviving inside you.",
    "What would make this night feel like it was worth being awake for?",
    "You're not behind on sleep. You're ahead on something else.",
    "The people you love are sleeping. You're here, working something out. Both are okay.",
    "What do you want to know about yourself that you can only find in this quiet?",
    "The night has held a lot. It can hold this too.",
    "What would you say to yourself right now if you were your own best friend?",
    "This isn't the last hard night. It's also not permanent.",
    "Something real is happening here. Let it.",
