    "Which part of what's keeping you up is solvable right now, and which part needs daylight?",
    "Are you getting somewhere in this thinking, or is it a loop?",
    "What would an outside observer say about what you're wrestling with right now?",
    "What are you most afraid to be honest about at this hour?",
    "The night amplifies some things out of proportion. Which part of this is that?",
    "What's the most honest thing you could acknowledge right now, even if you're not ready to act on it?",
    "Is there something you need to say — even just to yourself — before you can rest?",
    "What's the difference between the thing that's keeping you up and the thing that's actually the problem?",
    "In the quiet of this hour — observe: what is actually present right now?",
    "Orient to what's real: what do you know for certain, and what are you imagining?",
    "What decision, made in the dark, would be trustworthy enough to hold in the morning?",
    "What's the small act that would let you rest?",
