    "The quietest hours have always produced the heaviest realizations and the lightest solutions.",
    "You are not the only person awake right now. Across this city, this country, this world — others are sitting exactly where you are.",
    "The night is patient. It will hold what you bring to it without agenda.",
    "Every person who has ever made something real has spent nights like this one, unsure, awake, working.",
    "The morning after a night like this is different than a morning without one.",
    "What you confront in the dark doesn't have to be faced the same way in the light. But you have to confront it here first.",
    "The things that come up in the quiet are not mistakes. They are what you actually need to work with.",
    "Night is the place where pretending is expensive and honesty is free.",
    "The hardest nights have always made the most room for what comes next.",
