    "Orient: what does this moment actually call for — action, understanding, or rest?",
    "What decision, made right now, would let you rest?",
    "The smallest true act available to you in the dark — what is it?",
    "Observe: what is your body telling you that your mind has been drowning out?",
    "Given what you know at this hour — what's clear that wasn't clear this morning?",
    "What do you need to decide before you can sleep?",
