    "The fact that you're processing something difficult means you're paying attention. Most people look away.",
    "Every person in this world is carrying something they haven't told anyone. You're not alone in that.",
    "Time does something to hard things that you can't replicate with willpower alone. Some things need to be waited through.",
    "The things worth building always take longer and cost more than you thought they would. That's the universal fee.",
    "Understanding your situation clearly is step one. Most people skip it and wonder why they're making the same decisions again.",
    "What seems obvious in retrospect is usually not obvious in the moment. Give yourself credit for navigating with incomplete information.",
    "Everyone is in some version of an in-between. The transition never looks like much from inside it.",
    "You are not your current situation. You're the person navigating it. Those are different.",
    "Silence is underrated. You don't always need to be talking or processing or figuring. Sometimes you need to let it settle.",
    "The most honest version of where you are is usually better data than the most optimistic or pessimistic version.",
    "Where you are is where you are. The question is what you do from here.",
    "Taking stock of the actual situation — not the story you want it to be — is the most useful thing you can do right now.",
    "What's one thing you can do about this today? Not a plan. Not a resolution. What is the one thing?",
    "Most situations improve faster when you stop waiting for them to and start deciding to move.",
    "The gap between where you are and where you want to be is real. What's your current strategy for closing it?",
    "Understanding is important. Execution is what changes anything. What's your next execution?",
    "Being in-between is uncomfortable. Being in-between intentionally is a strategy. Make it intentional.",
