  'Parents who stayed in the room even when it was hard always had better outcomes than those who retreated.',
  'The need for teenagers to find themselves by pushing against the people who love them is not new.',
  'Parents who modeled repair after conflict always built better relationships than those who modeled perfection.',
  'Love expressed through presence has always mattered more than love expressed through gifts or solutions.',
  'The best thing you can do for your kid is do the work on yourself. They learn what they see.',
  'Your kid is watching how you handle hard things. Are you showing them what you want them to learn?',
  'You can\'t regulate your teenager if you can\'t regulate yourself. That\'s where it starts.',
  'The work you do on your own emotional intelligence directly transfers to your kid. Invest in it.',
  'Your presence — calm, consistent, engaged — is the highest-value intervention you have.',
  'You don\'t have to be perfect. You have to be real, growing, and accountable. That\'s better than perfect.',
  'The relationship repair you do — owning mistakes, coming back — teaches more than any correction.',
  'Your kid doesn\'t need you to have all the answers. They need you to be honest that you\'re trying.',
  'Every time you stay regulated in a hard moment, you\'re giving your kid a template for adulthood.',
  'The long game in parenting is about who your kid becomes. That\'s shaped by who you are when things are hard.',
