    "Observe what's actually happening with your teen, separated from your interpretation of what it means.",
    "Orient: given what you're actually seeing — not fearing, actually seeing — what does this situation tell you?",
    "What's the most important thing to decide here? Not everything, just the most important thing.",
    "What action could you take in the next 48 hours that would change something real in this relationship?",
    "Get clear on the facts before you respond. What do you actually know for certain?",
    "What would your teenager need to see from you to feel safe enough to tell you what's really going on?",
    "Act from your best self, not your most reactive self. What does your best self do in this situation?",
    "You've observed, you've reflected. What's the move that your relationship needs right now?",
    "What is the one thing your teen most needs from you right now, and are you providing it?",
    "Observe without judgment first. Then everything else.",
    "You don't have to get it all right. You have to stay in relationship with your kid while you figure it out.",
    "Your teenager is not trying to be difficult. They are trying to figure out who they are. Those feel the same from the outside.",
    "The most important question is not 'what did they do' but 'what do they need'.",
    "Connection before correction. Always in that order.",
    "Your teen notices everything you do and half of what you say. Calibrate accordingly.",
    "Sometimes the best parenting move is to say less and be more present.",
    "The relationship has reserves if you've been building them. And you can build them starting now if you haven't.",
    "What your teenager says they don't want from you is often exactly what they need, offered a little differently.",
    "You can disagree with a choice and still support the person who made it. That's an advanced skill worth developing.",
    "Hard conversations are better than silence that turns into distance. Even imperfect conversations.",
    "Your teen's job is to become separate from you. That's not rejection — that's success.",
    "There's a difference between being right and being effective. Know which one you're going for.",
    "What would it feel like for your teenager to know that you're proud of who they are, not just what they achieve?",
    "The version of parenting where you're always in control is not the version that produces connected adults.",
    "You're doing more right than you think. And there's room to do one thing better. Find the one thing.",
    "The fact that this is hard is proof it matters. Easy doesn't mean good.",
    "You don't have to have the right answer to be a good parent. You just have to stay curious about your kid.",
    "What would you want your teenager to remember about how you handled this particular season?",
    "Repair is available. It's almost never too late to try.",
    "Your teenager needs you more than they're currently showing you. That's developmentally normal. Stay close.",
    "What you give to the relationship right now will compound — in their trust, in their openness, in the adult they become.",
    "Being a great parent doesn't mean your kid never struggles. It means they don't struggle alone.",
