    "Every generation of parents has believed they faced the hardest parenting context in history. This is always true and never the complete picture.",
    "The child who felt truly known by a parent grows up with a different relationship to being known. You are building that capacity in them right now.",
    "What your teenager needs most from you changes every year. Staying curious about that is the job.",
    "No one parents well under sustained stress. Taking care of yourself is parenting.",
    "The version of 'getting it right' that matters is: keeping the relationship intact and growing through the hard moments.",
    "Parents have always worried. That worry, channeled well, becomes wisdom. Channeled badly, it becomes pressure your kid carries.",
